class Solution {
public:
    vector<int> rowAndMaximumOnes(vector<vector<int>>& mat) {
        int bi = 0, bc = -1;
        for (int i = 0; i < (int)mat.size(); i++) {
            int c = accumulate(mat[i].begin(), mat[i].end(), 0);
            if (c > bc) { bc = c; bi = i; }
        }
        return {bi, bc};
    }
};

