class Solution {
    public int[] rowAndMaximumOnes(int[][] mat) {
        int bi = 0, bc = -1;
        for (int i = 0; i < mat.length; i++) {
            int c = 0;
            for (int v : mat[i]) c += v;
            if (c > bc) { bc = c; bi = i; }
        }
        return new int[]{bi, bc};
    }
}

